#!/usr/bin/env bash
# Mesa for the Galaxy Tab S7 LTE (gts7l, Adreno 650): freedreno (EGL, GLES 1/2/3) and Turnip
# (Vulkan), cross built with meson for Android arm64 from AOSP 17's own sources
# (aosp/external/mesa3d, aosp/external/libdrm), installed as Soong prebuilts.
#
# Why not Soong: AOSP 17's external/mesa3d ships Android.bp files (generated by meson2hermetic)
# only for lavapipe, zink and gfxstream; freedreno and Turnip have none. Mesa's Android.mk
# meson wrapper (LineageOS external/mesa, as gts7xl-mainline uses) needs Kati, and aosp_gts7l
# is PRODUCT_SOONG_ONLY. So this is Mesa's upstream Android route (the one Mesa CI uses):
# meson with the NDK and -Dandroid-stub=true, whose stub libraries only satisfy the link;
# at runtime the libraries bind to the platform's liblog, libcutils, libsync, libhardware and
# libnativewindow. libdrm is built from external/libdrm as a static library and linked in.
#
# Steps (default: all, in order):
#   libdrm     static libdrm (core only) for aarch64-linux-android into out/gts7l-mesa/stage
#   configure  meson setup of Mesa in out/gts7l-mesa/mesa (re-run when options change)
#   build      ninja through tools/limited-build.sh (E-cores, -j8 at most)
#   install    out/gts7l-mesa/prebuilt/: the stripped libraries plus an Android.bp with
#              vendor cc_prebuilt_library_shared modules; tools/aosp-device-link.sh copies it
#              to aosp/device/android-pc/gts7l-mesa, which aosp_gts7l.mk picks up
#
# Installed on vendor (lib64): egl/libEGL_mesa.so, egl/libGLESv1_CM_mesa.so,
# egl/libGLESv2_mesa.so, libgallium_dri.so (the gallium megadriver they link) and
# hw/vulkan.freedreno.so (ro.hardware.egl=mesa, ro.hardware.vulkan=freedreno).
#
# Knobs: ANDROID_NDK (default /opt/android-ndk, r30 tested), GTS7L_MESA_API (default 37,
# AOSP 17), GTS7L_MESA_SRC, GTS7L_LIBDRM_SRC, GTS7L_MESA_OUT, JOBS (default 8, never more).
#
# Usage: tools/gts7l-mesa.sh [libdrm|configure|build|install|all]...
set -euo pipefail

REPO=$(cd "$(dirname "$0")/.." && pwd)
MAIN=$(dirname "$(cd "$REPO" && realpath "$(git rev-parse --git-common-dir)")")
NDK=${ANDROID_NDK:-/opt/android-ndk}
API=${GTS7L_MESA_API:-37}
MESA_SRC=${GTS7L_MESA_SRC:-$MAIN/aosp/external/mesa3d}
LIBDRM_SRC=${GTS7L_LIBDRM_SRC:-$MAIN/aosp/external/libdrm}
OUT=${GTS7L_MESA_OUT:-$MAIN/out/gts7l-mesa}
STAGE=$OUT/stage
PREBUILT=$OUT/prebuilt
CROSS=$OUT/aarch64-android.ini
JOBS=${JOBS:-8}

die() { echo "gts7l-mesa: $*" >&2; exit 1; }
log() { echo "==> $*"; }

(( JOBS <= 8 )) || die "JOBS=$JOBS: at most 8 (E-cores only)"
TC=$NDK/toolchains/llvm/prebuilt/linux-x86_64
[[ -x $TC/bin/aarch64-linux-android$API-clang ]] || die "no NDK clang for API $API in $NDK"
[[ -f $MESA_SRC/meson.build && -f $LIBDRM_SRC/meson.build ]] || die "no Mesa/libdrm sources"
python3 -c 'import mako, yaml, packaging' 2>/dev/null || die "host Python needs mako, pyyaml, packaging"

# Nothing may land in the AOSP source tree: no subproject downloads (meson unpacks them into
# external/mesa3d/subprojects, where Soong would see them) and no __pycache__ from Mesa's
# generators.
export PYTHONDONTWRITEBYTECODE=1

limited() { "$REPO/tools/limited-build.sh" "$@"; }

write_cross() {
    mkdir -p "$OUT"
    # libc++ is linked statically: the platform's libc++.so is not an NDK ABI.
    cat >"$CROSS.tmp" <<EOF
[binaries]
c = '$TC/bin/aarch64-linux-android$API-clang'
cpp = '$TC/bin/aarch64-linux-android$API-clang++'
ar = '$TC/bin/llvm-ar'
strip = '$TC/bin/llvm-strip'
objcopy = '$TC/bin/llvm-objcopy'
pkg-config = 'pkg-config'

[properties]
needs_exe_wrapper = true
pkg_config_libdir = '$STAGE/lib/pkgconfig'

[built-in options]
c_args = ['-O2', '-g0']
cpp_args = ['-O2', '-g0']
cpp_link_args = ['-static-libstdc++']

[host_machine]
system = 'android'
cpu_family = 'aarch64'
cpu = 'armv8'
endian = 'little'
EOF
    cmp -s "$CROSS.tmp" "$CROSS" && rm -f "$CROSS.tmp" || mv "$CROSS.tmp" "$CROSS"
}

do_libdrm() {
    write_cross
    local b=$OUT/libdrm
    if [[ ! -f $b/build.ninja ]]; then
        log "libdrm: configure ($LIBDRM_SRC)"
        meson setup "$b" "$LIBDRM_SRC" --cross-file "$CROSS" --prefix "$STAGE" \
            --libdir lib --buildtype release --wrap-mode=nofallback -Ddefault_library=static -Db_staticpic=true \
            -Dintel=disabled -Dradeon=disabled -Damdgpu=disabled -Dnouveau=disabled \
            -Dvmwgfx=disabled -Domap=disabled -Dexynos=disabled -Dfreedreno=disabled \
            -Dtegra=disabled -Dvc4=disabled -Detnaviv=disabled -Dcairo-tests=disabled \
            -Dman-pages=disabled -Dvalgrind=disabled -Dtests=false -Dudev=false \
            -Dinstall-test-programs=false
    fi
    log "libdrm: build and install into $STAGE"
    limited ninja -C "$b" -j"$JOBS" install
}

MESA_OPTS=(
    --cross-file "$CROSS" --prefix /vendor --libdir lib64 --buildtype release --wrap-mode=nofallback
    -Db_ndebug=true
    -Dplatforms=android -Dplatform-sdk-version="$API" -Dandroid-stub=true
    -Dandroid-libbacktrace=disabled -Dandroid-strict=true
    -Dgallium-drivers=freedreno -Dvulkan-drivers=freedreno -Dfreedreno-kmds=msm
    -Degl=enabled -Dgles1=enabled -Dgles2=enabled -Dopengl=true
    -Degl-lib-suffix=_mesa -Dgles-lib-suffix=_mesa
    -Dllvm=disabled -Dvalgrind=disabled -Dlibunwind=disabled -Dzstd=disabled
    -Dexpat=disabled -Dxmlconfig=disabled -Dperfetto=false -Dbuild-tests=false
    -Dvulkan-layers= -Dtools= -Dgallium-va=disabled -Dgallium-mediafoundation=disabled
    -Dgbm=disabled -Dglx=disabled -Dmicrosoft-clc=disabled -Dintel-rt=disabled
    -Dspirv-to-dxil=false
)

opts_id() { printf '%s\n' "${MESA_OPTS[@]}"; cat "$CROSS"; }

do_configure() {
    write_cross
    [[ -f $STAGE/lib/pkgconfig/libdrm.pc ]] || die "run the libdrm step first"
    local b=$OUT/mesa stamp=$OUT/mesa.opts
    if [[ -f $b/build.ninja ]] && opts_id | cmp -s - "$stamp"; then
        log "configure: up to date"; return
    fi
    log "configure: Mesa $(cat "$MESA_SRC/VERSION") for Android $API arm64"
    if [[ -f $b/build.ninja ]]; then
        meson setup --reconfigure "$b" "$MESA_SRC" "${MESA_OPTS[@]}"
    else
        meson setup "$b" "$MESA_SRC" "${MESA_OPTS[@]}"
    fi
    opts_id >"$stamp"
}

do_build() {
    [[ -f $OUT/mesa/build.ninja ]] || die "run the configure step first"
    log "build: ninja -j$JOBS"
    limited ninja -C "$OUT/mesa" -j"$JOBS"
}

# The installed name of each library -> its file in the build tree (found by name).
declare -A LIBS=(
    [libEGL_mesa]=libEGL_mesa.so
    [libGLESv1_CM_mesa]=libGLESv1_CM_mesa.so
    [libGLESv2_mesa]=libGLESv2_mesa.so
    [libgallium_dri]=libgallium_dri.so
    [vulkan.freedreno]=libvulkan_freedreno.so
)
declare -A SUBDIR=(
    [libEGL_mesa]=egl [libGLESv1_CM_mesa]=egl [libGLESv2_mesa]=egl
    [libgallium_dri]= [vulkan.freedreno]=hw
)

# Platform libraries a module may need at runtime (the stubs' real counterparts).
PLATFORM_LIBS=(libc libdl libm liblog libcutils libsync libhardware libnativewindow libz)

needed() { "$TC/bin/llvm-readelf" -d "$1" | sed -n 's/.*(NEEDED).*\[\(.*\)\.so\]/\1/p'; }

do_install() {
    local b=$OUT/mesa name f
    rm -rf "$PREBUILT.tmp"; mkdir -p "$PREBUILT.tmp"
    {
        echo "// Generated by tools/gts7l-mesa.sh from Mesa $(cat "$MESA_SRC/VERSION")"
        echo "// ($(git -C "$MESA_SRC" describe --always --dirty 2>/dev/null || echo unknown)); do not edit."
        echo
        echo 'package { default_applicable_licenses: ["gts7l_mesa_license"] }'
        echo
        echo 'license {'
        echo '    name: "gts7l_mesa_license",'
        echo '    license_kinds: ["SPDX-license-identifier-MIT"],'
        echo '    license_text: ["LICENSE"],'
        echo '}'
    } >"$PREBUILT.tmp/Android.bp"
    cp "$MESA_SRC/docs/license.rst" "$PREBUILT.tmp/LICENSE"
    for name in $(printf '%s\n' "${!LIBS[@]}" | sort); do
        f=$(find "$b" -name "${LIBS[$name]}" -type f -o -name "${LIBS[$name]}" -type l | head -1)
        [[ -n $f ]] || die "install: ${LIBS[$name]} not built"
        "$TC/bin/llvm-strip" --strip-unneeded -o "$PREBUILT.tmp/$name.so" "$(realpath "$f")"
        local deps=() d
        for d in $(needed "$PREBUILT.tmp/$name.so"); do
            if [[ -n ${LIBS[$d]:-} ]]; then deps+=("$d")
            elif printf '%s\n' "${PLATFORM_LIBS[@]}" | grep -qx "$d"; then
                [[ $d == libc || $d == libdl || $d == libm ]] || deps+=("$d")
            else die "install: $name.so needs $d.so, which is neither Mesa nor platform"
            fi
        done
        {
            echo
            echo 'cc_prebuilt_library_shared {'
            echo "    name: \"$name\","
            echo '    vendor: true,'
            echo '    compile_multilib: "64",'
            [[ -n ${SUBDIR[$name]} ]] && echo "    relative_install_path: \"${SUBDIR[$name]}\","
            echo "    srcs: [\"$name.so\"],"
            echo '    strip: { none: true },'
            # The Vulkan HAL is loaded by path (hw/vulkan.<ro.hardware.vulkan>.so); Mesa's
            # SONAME stays libvulkan_freedreno.so, which Soong's ELF check would reject.
            [[ $name == vulkan.* ]] && echo '    check_elf_files: false,'
            if ((${#deps[@]})); then
                printf '    shared_libs: ['; printf '"%s", ' "${deps[@]}" | sed 's/, $//'; echo '],'
            fi
            echo '}'
        } >>"$PREBUILT.tmp/Android.bp"
    done
    rm -rf "$PREBUILT"; mv "$PREBUILT.tmp" "$PREBUILT"
    log "install: $PREBUILT"; ls -l "$PREBUILT"
}

steps=("$@"); ((${#steps[@]})) || steps=(all)
for s in "${steps[@]}"; do
    case $s in
        libdrm) do_libdrm ;;
        configure) do_configure ;;
        build) do_build ;;
        install) do_install ;;
        all) do_libdrm; do_configure; do_build; do_install ;;
        *) die "unknown step $s" ;;
    esac
done
